function parseReplacementResumeInvocation(
  argument,
  maximumReplacementInvocations = 5,
) {
  if (
    maximumReplacementInvocations !==
    MAXIMUM_PRE_RUNTIME_REPLACEMENT_INVOCATIONS
  ) {
    fail("REPLACEMENT_RESUME_INVOCATION_MAXIMUM");
  }
  const prefix = "--replacement-invocation=";
  if (argument === undefined) return 1;
  if (typeof argument !== "string" || !argument.startsWith(prefix)) {
    fail("REPLACEMENT_RESUME_INVOCATION_ARGUMENT");
  }
  const replacementInvocation = Number(argument.slice(prefix.length));
  if (
    !Number.isInteger(replacementInvocation) ||
    replacementInvocation < 1 ||
    replacementInvocation > maximumReplacementInvocations ||
    argument !== `${prefix}${replacementInvocation}`
  ) {
    fail("REPLACEMENT_RESUME_INVOCATION_BOUND");
  }
  return replacementInvocation;
}
