function runProtectedPreviewTotalDeadlineSelfTest() {
  let firstCallback = null;
  let firstCleared = 0;
  let firstDelay = null;
  let firstDestroyedWith = null;
  const clearFirst = armProtectedPreviewTotalDeadline(
    {
      destroy(error) {
        firstDestroyedWith = error?.code ?? null;
      },
    },
    {
      clearTimer(timer) {
        if (timer !== "first-total-deadline") {
          fail("SELF_TEST_PROTECTED_PREVIEW_TOTAL_DEADLINE_TIMER");
        }
        firstCleared += 1;
      },
      setTimer(callback, milliseconds) {
        firstCallback = callback;
        firstDelay = milliseconds;
        return "first-total-deadline";
      },
    },
  );
  if (
    typeof firstCallback !== "function" ||
    firstDelay !== DIRECT_REQUEST_TIMEOUT_MS ||
    firstDestroyedWith !== null ||
    clearFirst() !== true ||
    firstCleared !== 1
  ) {
    fail("SELF_TEST_PROTECTED_PREVIEW_TOTAL_DEADLINE_CANCEL");
  }
  firstCallback();
  if (firstDestroyedWith !== null || clearFirst() !== false) {
    fail("SELF_TEST_PROTECTED_PREVIEW_TOTAL_DEADLINE_CANCELLED_FIRE");
  }

  let secondCallback = null;
  let secondDestroyedWith = null;
  const clearSecond = armProtectedPreviewTotalDeadline(
    {
      destroy(error) {
        secondDestroyedWith = error?.code ?? null;
      },
    },
    {
      clearTimer() {
        fail("SELF_TEST_PROTECTED_PREVIEW_TOTAL_DEADLINE_FIRED_CLEAR");
      },
      setTimer(callback, milliseconds) {
        if (milliseconds !== DIRECT_REQUEST_TIMEOUT_MS) {
          fail("SELF_TEST_PROTECTED_PREVIEW_TOTAL_DEADLINE_BOUND");
        }
        secondCallback = callback;
        return "second-total-deadline";
      },
    },
  );
  secondCallback();
  if (
    secondDestroyedWith !== "PROTECTED_PREVIEW_HTTP_TOTAL_DEADLINE" ||
    clearSecond() !== false
  ) {
    fail("SELF_TEST_PROTECTED_PREVIEW_TOTAL_DEADLINE_FIRE");
  }

  const durableWindowStart = Date.parse("2026-08-12T12:00:00.000Z");
  const durableRequestDeadline =
    durableWindowStart + DIRECT_REQUEST_TIMEOUT_MS;
  const delayedDispatchAt = durableWindowStart + 20_000;
  let delayedDispatchDelay = null;
  const clearDelayedDispatch = armProtectedPreviewTotalDeadline(
    { destroy() {} },
    {
      clearTimer() {},
      deadlineAt: durableRequestDeadline,
      now: () => delayedDispatchAt,
      setTimer(_callback, milliseconds) {
        delayedDispatchDelay = milliseconds;
        return "delayed-dispatch-total-deadline";
      },
    },
  );
  if (
    delayedDispatchDelay !== 10_000 ||
    clearDelayedDispatch() !== true ||
    !catchesForSelfTest(() =>
      armProtectedPreviewTotalDeadline(
        { destroy() {} },
        {
          clearTimer() {},
          deadlineAt: durableRequestDeadline,
          now: () => durableRequestDeadline,
          setTimer() {
            fail("SELF_TEST_PROTECTED_PREVIEW_EXPIRED_DISPATCH_TIMER");
          },
        },
      ),
    )
  ) {
    fail("SELF_TEST_PROTECTED_PREVIEW_DURABLE_DEADLINE_BINDING");
  }
}

async function runDelta18QualificationLogoutMutationWindowSelfTest(plan) {
  const tempRoot = createCanonicalTempRoot(
    DELTA18_TEMP_ROOT_PREFIX,
  ).canonical_temp_root;
  const runMarker = "00000000-0000-4000-8000-000000000019";
  const durableEvidence = createDelta18DurableEvidenceState({
    cleanupIdentity: {
      commit_sha: "c".repeat(40),
      deployment_id: "dpl_Delta18LogoutWindowSelfTest",
    },
    kind: "QUALIFICATION",
    plan,
    runMarker,
    tempRoot,
  });
  durableEvidence.entries = [{}, {}, {}, {}];
  durableEvidence.journalSha256 = "d".repeat(64);
  durableEvidence.lastAttemptedSequenceOrdinal = 5;
  const mutationWindowStartedAt = Date.parse("2026-08-12T12:00:00.000Z");
  let clock = mutationWindowStartedAt;
  let delayedAuditCommitted = false;
  let completedErrorResponseRejected = false;
  let unresolvedMutationRejected = false;
  let waitCalls = 0;
  let queryCalls = 0;
  let deleteCalls = 0;
  const rows = [];
  const budgets = new Delta15QualificationBudgets();
  const direct = {
    client: {
      from(tableName) {
        if (tableName !== "admin_audit_logs") {
          fail("SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_TABLE");
        }
        const filters = [];
        let operation = "SELECT";
        let exactCas = false;
        const builder = {
          delete() {
            operation = "DELETE";
            return builder;
          },
          eq(name, value) {
            filters.push([name, value]);
            return builder;
          },
          or(value) {
            if (
              operation !== "DELETE" ||
              typeof value !== "string" ||
              !value.includes("id.eq.19") ||
              !value.includes("action.eq.\"admin_logout\"") ||
              !value.includes(`user_agent.eq.\"${durableEvidence.userAgent}\"`)
            ) {
              fail("SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_EXACT_CAS");
            }
            exactCas = true;
            return builder;
          },
          select(columns) {
            if (
              columns !==
              DELTA17A_PRIOR_TABLE_CONTRACTS.admin_audit_logs.columns
            ) {
              fail(
                "SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_FULL_ROW_CAS",
              );
            }
            return builder;
          },
          then(resolve, reject) {
            budgets.take("directDataMaximum");
            const matches = rows.filter((row) =>
              filters.every(([name, value]) => row[name] === value),
            );
            if (operation === "SELECT") {
              queryCalls += 1;
              if (!delayedAuditCommitted) {
                fail("SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_EARLY_QUERY");
              }
            } else {
              if (!exactCas) {
                fail("SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_EXACT_CAS");
              }
              deleteCalls += 1;
              for (const match of matches) {
                rows.splice(rows.indexOf(match), 1);
              }
            }
            return Promise.resolve({
              data: operation === "SELECT"
                ? matches.map((row) => ({ ...row }))
                : matches.map((row) => structuredClone(row)),
              error: null,
            }).then(resolve, reject);
          },
        };
        return builder;
      },
    },
    success() {
      budgets.take("directDataSuccess");
    },
  };
  try {
    persistDelta18QualificationLogoutMutationWindow(durableEvidence, {
      now: () => clock,
    });
    durableEvidence.entries.push({});
    completedErrorResponseRejected = catchesForSelfTest(() =>
      confirmDelta18QualificationLogoutMutationWindowAfterValidation({
        durableEvidence,
        validationComplete: false,
      }),
    );
    if (
      !completedErrorResponseRejected ||
      durableEvidence.logoutMutationConfirmedClosed !== false
    ) {
      fail("SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_ERROR_RESPONSE");
    }
    clock += DELTA18_QUALIFICATION_LOGOUT_MUTATION_TAIL_MS + 1;
    try {
      await cleanupDelta18QualificationLogoutAudit({
        budgets,
        direct,
        durableEvidence,
        mutationWindowHooks: {
          now: () => clock,
          async wait(milliseconds) {
            waitCalls += 1;
            if (
              milliseconds !==
              DIRECT_REQUEST_TIMEOUT_MS - 1
            ) {
              fail("SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_WAIT_BOUND");
            }
            clock += milliseconds;
            rows.push({
              action: "admin_logout",
              created_at: "2026-08-12T12:00:30.000Z",
              details: {},
              id: 19,
              ip_address: null,
              target_id: null,
              target_name: null,
              target_type: null,
              user_agent: durableEvidence.userAgent,
            });
            delayedAuditCommitted = true;
          },
        },
        requireCreated: false,
      });
    } catch (caught) {
      unresolvedMutationRejected =
        categoricalErrorCode(caught) ===
        "DELTA18_QUALIFICATION_LOGOUT_MUTATION_UNRESOLVED";
    }
    const locatorBytes = readRegularFile(
      path.join(tempRoot, DELTA18_INCREMENTAL_LOCATOR_FILENAME),
      { mode: 0o600, maximum: 64 * 1024 },
    );
    let locator;
    try {
      locator = validateDelta18IncrementalCleanupLocators(
        parseJsonBuffer(
          locatorBytes,
          "SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_LOCATOR",
        ),
        plan,
      );
    } finally {
      locatorBytes.fill(0);
    }
    if (
      !unresolvedMutationRejected ||
      rows.length !== 0 ||
      !completedErrorResponseRejected ||
      waitCalls !== 1 ||
      queryCalls !== 3 ||
      deleteCalls !== 1 ||
      budgets.used.directDataMaximum !== 4 ||
      budgets.used.directDataSuccess !== 4 ||
      budgets.used.absenceVerificationQueries !== 3 ||
      budgets.used.auditCleanupRequests !== 1 ||
      durableEvidence.logoutMutationConfirmedClosed !== false ||
      locator.logout_mutation_confirmed_closed !== false ||
      locator.logout_mutation_window_end !==
        new Date(
          mutationWindowStartedAt +
            DELTA18_QUALIFICATION_LOGOUT_MUTATION_WINDOW_MS,
        ).toISOString()
    ) {
      fail("SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_UNRESOLVED");
    }
  } finally {
    if (existsSync(tempRoot)) {
      removeDelta18DurableEvidenceFiles(tempRoot);
      if (readdirSync(tempRoot).length !== 0) {
        fail("SELF_TEST_DELTA18_QUALIFICATION_LOGOUT_ROOT_RESIDUE");
      }
      rmdirSync(tempRoot);
      fsyncExactDirectory(realpathSync.native(tmpdir()));
    }
  }
}

async function runDelta20ExactCleanupCasSelfTest(plan) {
  const marker = "00000000-0000-4000-8000-000000000020";
  if (
    delta17APostgrestCasLiteral([]) !== 'eq."{}"' ||
    delta17APostgrestCasLiteral(["web", "ios"]) !==
      'eq."{\\"web\\",\\"ios\\"}"' ||
    delta17APostgrestCasLiteral({ marker, nested: { exact: true } }) !==
      `eq."{\\"marker\\":\\"${marker}\\",\\"nested\\":{\\"exact\\":true}}"`
  ) {
    fail("SELF_TEST_DELTA20_EXACT_CLEANUP_CAS_LITERALS");
  }
  const exactRow = Object.freeze({
    category: "Productivity",
    created_at: "2026-08-13T00:00:00.000Z",
    description: "Bounded synthetic Admin V1 staging edit fixture updated.",
    id: 20,
    logo_url: null,
    name: "34IA EDIT 00000000 UPDATED",
    normalized_domain: `edit-${marker}.invalid`,
    pricing: "Free",
    status: "pending",
    submitter_email: "phase34ia@example.invalid",
    submitter_name: "AiFinder Phase 34IA",
    website: `https://edit-updated-${marker}.invalid/`,
  });
  const records = delta17AClassifyPriorRows(
    [exactRow],
    classifyDelta17APriorSubmissionRow,
    "SELF_TEST_DELTA20_EXACT_CLEANUP_RECORD",
  ).exact;
  if (records.length !== 1) {
    fail("SELF_TEST_DELTA20_EXACT_CLEANUP_RECORD");
  }
  const progress = () => ({
    deleteAttempted: new Set(),
    deleted: new Set(),
    residue: new Set(),
    verified: new Set(),
    verifyAttempted: new Set(),
  });
  const mockDirect = ({ ambiguousReplacement = false } = {}) => {
    const state = [structuredClone(exactRow)];
    let deleteCalls = 0;
    let successes = 0;
    let casFilter = null;
    return {
      beginCleanup() {},
      client: {
        from(table) {
          if (table !== "submitted_tools") {
            fail("SELF_TEST_DELTA20_EXACT_CLEANUP_TABLE");
          }
          let operation = "SELECT";
          let ids = null;
          const builder = {
            delete() {
              operation = "DELETE";
              return builder;
            },
            in(field, values) {
              if (field !== "id") {
                fail("SELF_TEST_DELTA20_EXACT_CLEANUP_SELECTOR");
              }
              ids = values;
              return builder;
            },
            or(value) {
              casFilter = value;
              return builder;
            },
            select() {
              return builder;
            },
            then(resolve, reject) {
              if (operation === "SELECT") {
                return Promise.resolve({
                  data: state
                    .filter((row) => ids.includes(row.id))
                    .map((row) => structuredClone(row)),
                  error: null,
                }).then(resolve, reject);
              }
              deleteCalls += 1;
              if (ambiguousReplacement && deleteCalls === 1) {
                state[0].description = "concurrent replacement";
                return Promise.resolve({
                  data: null,
                  error: { message: "synthetic ambiguous transport" },
                }).then(resolve, reject);
              }
              const deleted = state.splice(0).map((row) => structuredClone(row));
              return Promise.resolve({ data: deleted, error: null })
                .then(resolve, reject);
            },
          };
          return builder;
        },
      },
      state,
      success() {
        successes += 1;
      },
      observations() {
        return { casFilter, deleteCalls, successes };
      },
    };
  };

  const normalDirect = mockDirect();
  const normalProgress = progress();
  await cleanupDelta20ExactRows({
    budgets: new GlobalBudgets(plan),
    category: "submissions",
    direct: normalDirect,
    progress: normalProgress,
    records,
    table: "submitted_tools",
  });
  const normal = normalDirect.observations();
  if (
    normalDirect.state.length !== 0 ||
    normal.deleteCalls !== 1 ||
    normal.successes !== 2 ||
    !normalProgress.verified.has("submissions") ||
    !normal.casFilter.includes("id.eq.20") ||
    !normal.casFilter.includes(
      `normalized_domain.eq.\"edit-${marker}.invalid\"`,
    ) ||
    !normal.casFilter.includes(
      "created_at.eq.\"2026-08-13T00:00:00.000Z\"",
    )
  ) {
    fail("SELF_TEST_DELTA20_EXACT_CLEANUP_CAS_SUCCESS");
  }

  const replacementDirect = mockDirect({ ambiguousReplacement: true });
  const replacementProgress = progress();
  if (!(await rejectsForSelfTest(() => cleanupDelta20ExactRows({
    budgets: new GlobalBudgets(plan),
    category: "submissions",
    direct: replacementDirect,
    progress: replacementProgress,
    records,
    table: "submitted_tools",
  })))) {
    fail("SELF_TEST_DELTA20_EXACT_CLEANUP_REPLACEMENT_REJECTED");
  }
  const replacement = replacementDirect.observations();
  if (
    replacement.deleteCalls !== 1 ||
    replacementDirect.state.length !== 1 ||
    replacementDirect.state[0].description !== "concurrent replacement" ||
    !replacementProgress.residue.has("submissions") ||
    replacementProgress.verified.has("submissions")
  ) {
    fail("SELF_TEST_DELTA20_EXACT_CLEANUP_REPLACEMENT_PRESERVED");
  }

  const payload = createSyntheticLogoPayload(marker);
  const sameVersionReplacementPayload = createSyntheticLogoPayload(
    "00000000-0000-4000-8000-000000000021",
  );
  const initialStorageRecord = Object.freeze({
    bytes: payload.byteLength,
    CAS_outcome: null,
    expected_version: "storage-version-1",
    grant_expires_at: null,
    grant_id: null,
    grant_revoked: false,
    marker,
    name: `${marker}.png`,
    post_delete_absence: false,
    raw_token_persisted: false,
    replacement_preserved: "not_applicable",
    sha256: payload.sha256,
    storage_path: `admin/${marker}.png`,
    token_hash: null,
  });
  const storageScenario = ({
    deleteMode,
    initiallyAbsent = false,
    loseFirstPrepareResponse = false,
  }) => {
    const state = initiallyAbsent
      ? []
      : [selfTestLogoRow(`${marker}.png`, "1")];
    const persisted = [];
    let deleteCalls = 0;
    let infoCalls = 0;
    let prepareCalls = 0;
    let revokeCalls = 0;
    let successes = 0;
    let rawTokenSeen = null;
    let storedPayloadBytes = payload.bytes;
    const direct = {
      client: {
        storage: {
          from(bucket) {
            if (bucket !== LOGO_STORAGE_BUCKET) {
              fail("SELF_TEST_DELTA20_EXACT_STORAGE_BUCKET");
            }
            return {
              async download(objectPath) {
                if (objectPath !== `admin/${marker}.png`) {
                  fail("SELF_TEST_DELTA20_EXACT_STORAGE_PATH");
                }
                const bytes = Uint8Array.from(storedPayloadBytes);
                return {
                  data: {
                    size: bytes.byteLength,
                    async arrayBuffer() { return bytes.buffer; },
                  },
                  error: null,
                };
              },
              async list(directory) {
                if (directory !== LOGO_STORAGE_DIRECTORY) {
                  fail("SELF_TEST_DELTA20_EXACT_STORAGE_DIRECTORY");
                }
                return {
                  data: state.map((row) => structuredClone(row)),
                  error: null,
                };
              },
            };
          },
        },
      },
      storageCleanup: {
        async readExactObjectInfo({ storagePath }) {
          infoCalls += 1;
          if (storagePath !== initialStorageRecord.storage_path) {
            fail("SELF_TEST_STORAGE_CAS_INFO_PATH");
          }
          const row = state.find(
            (candidate) => candidate.name === initialStorageRecord.name,
          );
          if (!row) {
            return { data: null, error: { status: 404 } };
          }
          return {
            data: {
              bucketId: LOGO_STORAGE_BUCKET,
              name: storagePath,
              version: row.version,
            },
            error: null,
          };
        },
        async prepareGrant(input) {
          prepareCalls += 1;
          if (loseFirstPrepareResponse && prepareCalls === 1) {
            throw new Error("synthetic lost grant response");
          }
          return {
            data: [{
              expected_version: input.expectedVersion,
              expires_at: "2026-08-13T23:59:00.000Z",
              grant_id: input.grantId,
            }],
            error: null,
          };
        },
        async deleteExactObject({ rawToken, storagePath }) {
          deleteCalls += 1;
          rawTokenSeen = rawToken;
          if (
            storagePath !== initialStorageRecord.storage_path ||
            !/^[a-f0-9]{64}$/u.test(rawToken)
          ) {
            fail("SELF_TEST_STORAGE_CAS_ANON_DELETE_INPUT");
          }
          if (deleteMode === "AUTHORIZED") {
            state.splice(0);
            return { data: [], error: null };
          }
          if (deleteMode === "LOST_SAME_VERSION_CONTENT_REPLACEMENT") {
            storedPayloadBytes = sameVersionReplacementPayload.bytes;
            state.splice(
              0,
              state.length,
              selfTestLogoRow(`${marker}.png`, "1"),
            );
            throw new Error("synthetic lost delete response");
          }
          state.splice(0, state.length, selfTestLogoRow(`${marker}.png`, "2"));
          if (deleteMode === "FORBIDDEN_REPLACEMENT") {
            return { data: null, error: { status: 403 } };
          }
          throw new Error("synthetic lost delete response");
        },
        async revokeGrant() {
          revokeCalls += 1;
          return { data: true, error: null };
        },
      },
      success() {
        successes += 1;
      },
    };
    return {
      deleteCalls: () => deleteCalls,
      direct,
      infoCalls: () => infoCalls,
      persisted,
      prepareCalls: () => prepareCalls,
      rawTokenSeen: () => rawTokenSeen,
      revokeCalls: () => revokeCalls,
      state,
      successes: () => successes,
    };
  };
  try {
    const authorized = storageScenario({
      deleteMode: "AUTHORIZED",
      loseFirstPrepareResponse: true,
    });
    const authorizedBudgets = new GlobalBudgets(plan);
    const authorizedProgress = progress();
    await cleanupDelta20ExactStorage({
      budgets: authorizedBudgets,
      direct: authorized.direct,
      persistGrantRecord(storageRecord) {
        authorized.persisted.push(structuredClone(storageRecord));
      },
      progress: authorizedProgress,
      runtime: null,
      storageRecord: initialStorageRecord,
    });
    if (
      authorized.state.length !== 0 ||
      authorized.prepareCalls() !== 2 ||
      authorized.deleteCalls() !== 1 ||
      authorized.infoCalls() !== 1 ||
      authorized.revokeCalls() !== 1 ||
      authorized.successes() !== 2 ||
      authorized.persisted.length !== 2 ||
      authorized.persisted.at(-1).CAS_outcome !== "AUTHORIZED" ||
      authorized.persisted.at(-1).grant_revoked !== true ||
      authorized.persisted.at(-1).post_delete_absence !== true ||
      authorized.persisted.some((record) =>
        canonicalJson(record).includes(authorized.rawTokenSeen()),
      ) ||
      !authorizedProgress.verified.has("storage")
    ) {
      fail("SELF_TEST_STORAGE_CAS_LOST_GRANT_CREATE_RECONCILED_EXACTLY");
    }

    const recoveredAbsence = storageScenario({
      deleteMode: "AUTHORIZED",
      initiallyAbsent: true,
    });
    const recoveredAbsenceProgress = progress();
    const recoveredGrantRecord = Object.freeze({
      ...initialStorageRecord,
      grant_expires_at: "2026-08-13T23:59:00.000Z",
      grant_id: "123e4567-e89b-42d3-b456-426614174001",
      token_hash: "cd".repeat(32),
    });
    if (!(await rejectsForSelfTest(() => cleanupDelta20ExactStorage({
      budgets: new GlobalBudgets(plan),
      direct: recoveredAbsence.direct,
      persistGrantRecord(storageRecord) {
        recoveredAbsence.persisted.push(structuredClone(storageRecord));
      },
      progress: recoveredAbsenceProgress,
      runtime: null,
      storageRecord: recoveredGrantRecord,
    })))) {
      fail("SELF_TEST_STORAGE_CAS_RECOVERED_ABSENCE_AMBIGUOUS");
    }
    if (
      recoveredAbsence.state.length !== 0 ||
      recoveredAbsence.prepareCalls() !== 0 ||
      recoveredAbsence.deleteCalls() !== 0 ||
      recoveredAbsence.infoCalls() !== 0 ||
      recoveredAbsence.revokeCalls() !== 1 ||
      recoveredAbsence.successes() !== 0 ||
      recoveredAbsence.persisted.length !== 1 ||
      recoveredAbsence.persisted[0].CAS_outcome !== "AMBIGUOUS" ||
      recoveredAbsence.persisted[0].grant_revoked !== true ||
      recoveredAbsence.persisted[0].post_delete_absence !== true ||
      !recoveredAbsenceProgress.residue.has("storage") ||
      recoveredAbsenceProgress.verified.has("storage")
    ) {
      fail("SELF_TEST_STORAGE_CAS_RECOVERED_ABSENCE_AMBIGUOUS");
    }

    const replacement = storageScenario({
      deleteMode: "FORBIDDEN_REPLACEMENT",
    });
    const storageReplacementProgress = progress();
    if (!(await rejectsForSelfTest(() => cleanupDelta20ExactStorage({
      budgets: new GlobalBudgets(plan),
      direct: replacement.direct,
      persistGrantRecord(storageRecord) {
        replacement.persisted.push(structuredClone(storageRecord));
      },
      progress: storageReplacementProgress,
      runtime: null,
      storageRecord: initialStorageRecord,
    })))) {
      fail("SELF_TEST_STORAGE_CAS_REPLACEMENT_VERSION_REJECTED");
    }
    if (
      replacement.state.length !== 1 ||
      replacement.state[0].version !== "storage-version-2" ||
      replacement.deleteCalls() !== 1 ||
      replacement.infoCalls() !== 2 ||
      replacement.revokeCalls() !== 1 ||
      replacement.persisted.at(-1).CAS_outcome !== "VERSION_MISMATCH" ||
      replacement.persisted.at(-1).replacement_preserved !== true ||
      !storageReplacementProgress.residue.has("storage")
    ) {
      fail("SELF_TEST_STORAGE_CAS_REPLACEMENT_VERSION_PRESERVED");
    }

    const lostReplacement = storageScenario({
      deleteMode: "LOST_REPLACEMENT",
    });
    if (!(await rejectsForSelfTest(() => cleanupDelta20ExactStorage({
      budgets: new GlobalBudgets(plan),
      direct: lostReplacement.direct,
      persistGrantRecord(storageRecord) {
        lostReplacement.persisted.push(structuredClone(storageRecord));
      },
      progress: progress(),
      runtime: null,
      storageRecord: initialStorageRecord,
    })))) {
      fail("SELF_TEST_STORAGE_CAS_LOST_DELETE_REPLACEMENT_REJECTED");
    }
    if (
      lostReplacement.state.length !== 1 ||
      lostReplacement.state[0].version !== "storage-version-2" ||
      lostReplacement.deleteCalls() !== 1 ||
      lostReplacement.infoCalls() !== 2 ||
      lostReplacement.revokeCalls() !== 1 ||
      lostReplacement.persisted.at(-1).CAS_outcome !==
        "VERSION_MISMATCH" ||
      lostReplacement.persisted.at(-1).replacement_preserved !== true
    ) {
      fail("SELF_TEST_STORAGE_CAS_LOST_DELETE_REPLACEMENT_PRESERVED");
    }

    const sameVersionReplacement = storageScenario({
      deleteMode: "LOST_SAME_VERSION_CONTENT_REPLACEMENT",
    });
    if (!(await rejectsForSelfTest(() => cleanupDelta20ExactStorage({
      budgets: new GlobalBudgets(plan),
      direct: sameVersionReplacement.direct,
      persistGrantRecord(storageRecord) {
        sameVersionReplacement.persisted.push(
          structuredClone(storageRecord),
        );
      },
      progress: progress(),
      runtime: null,
      storageRecord: initialStorageRecord,
    })))) {
      fail(
        "SELF_TEST_STORAGE_CAS_SAME_VERSION_CONTENT_REPLACEMENT_REJECTED",
      );
    }
    if (
      sameVersionReplacement.state.length !== 1 ||
      sameVersionReplacement.state[0].version !== "storage-version-1" ||
      sameVersionReplacement.deleteCalls() !== 1 ||
      sameVersionReplacement.infoCalls() !== 2 ||
      sameVersionReplacement.revokeCalls() !== 1 ||
      sameVersionReplacement.persisted.at(-1).CAS_outcome !==
        "VERSION_MISMATCH" ||
      sameVersionReplacement.persisted.at(-1).replacement_preserved !== true
    ) {
      fail(
        "SELF_TEST_STORAGE_CAS_SAME_VERSION_CONTENT_REPLACEMENT_PRESERVED",
      );
    }

    let serviceRoleRejected = false;
    try {
      authorizeStorageCleanupDeleteClientRole("service_role");
    } catch (caught) {
      serviceRoleRejected =
        caught?.code === "STORAGE_CLEANUP_DELETE_CLIENT_ROLE";
    }
    if (!serviceRoleRejected) {
      fail("SELF_TEST_STORAGE_CAS_SERVICE_ROLE_DELETE_REJECTED");
    }
  } finally {
    payload.bytes.fill(0);
    sameVersionReplacementPayload.bytes.fill(0);
  }
}

function runDelta20InterruptedRuntimeClassificationSelfTest() {
  const marker = "55555555-5555-4555-8555-555555555555";
  const prefix = marker.slice(0, 8);
  const intent = (ordinal) => Object.freeze({
    cleanup_not_before_epoch_ms: 100_000 + ordinal,
    kind: ordinal === 5 ? "DIRECT_FIXTURE_SETUP" : "APPLICATION_MUTATION",
    ordinal,
    recorded_at_epoch_ms: 10_000 + ordinal,
  });
  const recovery = ({ completed, intents, attempted = completed }) =>
    Object.freeze({
      last_attempted_ordinal: attempted,
      last_completed_ordinal: completed,
      mutation_intents: Object.freeze(intents.map(intent)),
      run_marker: marker,
    });
  const expectClassification = (classifier, row, expected, code) => {
    const observed = classifier(row);
    if (
      observed.classification !== expected ||
      (expected === "EXACT_PHASE_OWNED" && observed.marker !== marker)
    ) {
      fail(code);
    }
  };
  const initialSubmission = Object.freeze({
    ...syntheticFixtures(marker)[0].row,
    created_at: "2026-08-13T00:00:00.000Z",
    id: 501,
  });
  const updatedSubmission = Object.freeze({
    ...initialSubmission,
    description: "Bounded synthetic Admin V1 staging edit fixture updated.",
    name: `34IA EDIT ${prefix} UPDATED`,
    website: `https://edit-updated-${marker}.invalid/`,
  });
  const routeCreated = Object.freeze({
    category: "Productivity",
    deleted_at: null,
    description: "Bounded synthetic Admin V1 runtime route fixture.",
    id: 601,
    logo_url: null,
    name: `34IA ROUTE ${prefix}`,
    normalized_domain: `route-${marker}.invalid`,
    pricing: "Free",
    status: "approved",
    website: `https://route-${marker}.invalid/`,
  });
  const routeUpdated = Object.freeze({
    ...routeCreated,
    description: "Bounded synthetic Admin V1 runtime route fixture updated.",
    name: `34IA ROUTE ${prefix} UPDATED`,
  });
  const routeArchived = Object.freeze({
    ...routeUpdated,
    deleted_at: "2026-08-13T00:01:00.000Z",
    status: "archived",
  });

  let classifiers = buildDelta20InterruptedRuntimeClassifiers(
    recovery({ attempted: 5, completed: 5, intents: [5] }),
  );
  expectClassification(
    classifiers.submissions,
    initialSubmission,
    "EXACT_PHASE_OWNED",
    "SELF_TEST_DELTA20_INTERRUPTED_INITIAL_FIXTURE",
  );
  classifiers = buildDelta20InterruptedRuntimeClassifiers(
    recovery({ attempted: 5, completed: 5, intents: [] }),
  );
  expectClassification(
    classifiers.submissions,
    initialSubmission,
    "OWNERSHIP_AMBIGUITY",
    "SELF_TEST_DELTA20_INTERRUPTED_FIXTURE_WITHOUT_INTENT",
  );
  classifiers = buildDelta20InterruptedRuntimeClassifiers(
    recovery({ attempted: 8, completed: 7, intents: [5, 8] }),
  );
  expectClassification(
    classifiers.tools,
    routeCreated,
    "EXACT_PHASE_OWNED",
    "SELF_TEST_DELTA20_INTERRUPTED_ROUTE_CREATE",
  );
  expectClassification(
    classifiers.tools,
    routeUpdated,
    "OWNERSHIP_AMBIGUITY",
    "SELF_TEST_DELTA20_INTERRUPTED_ROUTE_EARLY_UPDATE",
  );
  classifiers = buildDelta20InterruptedRuntimeClassifiers(
    recovery({ attempted: 10, completed: 9, intents: [5, 8, 10] }),
  );
  expectClassification(
    classifiers.tools,
    routeCreated,
    "EXACT_PHASE_OWNED",
    "SELF_TEST_DELTA20_INTERRUPTED_ROUTE_AMBIGUOUS_PRE",
  );
  expectClassification(
    classifiers.tools,
    routeUpdated,
    "EXACT_PHASE_OWNED",
    "SELF_TEST_DELTA20_INTERRUPTED_ROUTE_AMBIGUOUS_POST",
  );
  expectClassification(
    classifiers.submissions,
    updatedSubmission,
    "OWNERSHIP_AMBIGUITY",
    "SELF_TEST_DELTA20_INTERRUPTED_SUBMISSION_EARLY_UPDATE",
  );
  classifiers = buildDelta20InterruptedRuntimeClassifiers(
    recovery({ attempted: 12, completed: 11, intents: [5, 8, 10, 11, 12] }),
  );
  expectClassification(
    classifiers.tools,
    routeArchived,
    "EXACT_PHASE_OWNED",
    "SELF_TEST_DELTA20_INTERRUPTED_ROUTE_ARCHIVED",
  );
  expectClassification(
    classifiers.submissions,
    initialSubmission,
    "EXACT_PHASE_OWNED",
    "SELF_TEST_DELTA20_INTERRUPTED_SUBMISSION_AMBIGUOUS_PRE",
  );
  expectClassification(
    classifiers.submissions,
    updatedSubmission,
    "EXACT_PHASE_OWNED",
    "SELF_TEST_DELTA20_INTERRUPTED_SUBMISSION_AMBIGUOUS_POST",
  );
  expectClassification(
    classifiers.submissions,
    { ...updatedSubmission, description: "concurrent replacement" },
    "OWNERSHIP_AMBIGUITY",
    "SELF_TEST_DELTA20_INTERRUPTED_REPLACEMENT_PRESERVED",
  );
}

async function runDelta20MutationQuiescenceSelfTest() {
  const recordedAtEpochMs = 10_000;
  const intent = createDelta20MutationIntent({
    kind: "APPLICATION_MUTATION",
    ordinal: 15,
    recordedAtEpochMs,
  });
  if (
    intent.cleanup_not_before_epoch_ms !==
      recordedAtEpochMs + DELTA18_QUALIFICATION_LOGOUT_MUTATION_WINDOW_MS
  ) {
    fail("SELF_TEST_DELTA20_MUTATION_QUIESCENCE_DEADLINE");
  }
  let clock = recordedAtEpochMs + 1_000;
  const waits = [];
  await waitDelta20MutationQuiescence({
    intents: [intent],
    now: () => clock,
    async wait(milliseconds) {
      waits.push(milliseconds);
      clock += milliseconds;
    },
  });
  if (
    canonicalJson(waits) !== canonicalJson([
      DELTA18_QUALIFICATION_LOGOUT_MUTATION_WINDOW_MS - 1_000,
    ]) ||
    clock !== intent.cleanup_not_before_epoch_ms
  ) {
    fail("SELF_TEST_DELTA20_MUTATION_QUIESCENCE_WAIT");
  }
  if (!catchesForSelfTest(() => createDelta20MutationIntent({
    kind: "APPLICATION_MUTATION",
    ordinal: 15,
    recordedAtEpochMs: 0,
  }))) {
    fail("SELF_TEST_DELTA20_MUTATION_QUIESCENCE_INPUT");
  }
  const qualificationIntent = createDelta20QualificationMutationIntent({
    kind: "REGISTRATION_BRANCH_PUSH",
    recordedAtEpochMs,
    sequence: 1,
  });
  clock = qualificationIntent.cleanup_not_before_epoch_ms;
  await waitDelta20MutationQuiescence({
    intents: [qualificationIntent],
    now: () => clock,
    async wait() {
      fail("SELF_TEST_DELTA20_QUALIFICATION_QUIESCENCE_FALSE_WAIT");
    },
  });
  if (
    qualificationIntent.cleanup_not_before_epoch_ms !==
      recordedAtEpochMs + DELTA18_QUALIFICATION_LOGOUT_MUTATION_WINDOW_MS ||
    qualificationIntent.kind !== "REGISTRATION_BRANCH_PUSH" ||
    qualificationIntent.sequence !== 1
  ) {
    fail("SELF_TEST_DELTA20_QUALIFICATION_QUIESCENCE_INTENT");
  }
}

function validateDelta20SelfTestDocument(expected, code) {
  return (value) => {
    if (canonicalJson(value) !== canonicalJson(expected)) fail(code);
    return Object.freeze(JSON.parse(canonicalJson(value)));
  };
}

function cleanupDelta20PublicationSelfTestRoot(tempRoot) {
  const allowed = new Set([
    AUTHORIZATION_LOCK_FILENAME,
    DELTA19_QUALIFICATION_ATTEMPT_FILENAME,
    DELTA19_QUALIFICATION_TOMBSTONE_FILENAME,
    DELTA20_ACTIVE_AUTHORIZATION_LOCK_FILENAME,
    DELTA20_LINEAGE_RECEIPT_FILENAME,
    "delta20-cleanup-locators.json",
    "delta20-cleanup.receipt.json",
    "delta20-atomic-recovery.json",
    "delta20-atomic-recovery.json.next",
    "delta20-evidence.json",
    "delta20-publication-journal.json",
    "delta20-publication.receipt.json",
    "delta20-retirement.receipt.json",
    DELTA18_OFFICIAL_JOURNAL_FILENAME,
    DELTA18_INCREMENTAL_LOCATOR_FILENAME,
    DELTA20_RUNTIME_RETIREMENT_PROGRESS_FILENAME,
    DELTA20_RUNTIME_EXECUTION_RECOVERY_FILENAME,
    DELTA20_QUALIFICATION_EXECUTION_RECOVERY_FILENAME,
    DELTA20_QUALIFICATION_FINALIZATION_PROGRESS_FILENAME,
    `${DELTA20_QUALIFICATION_FINALIZATION_PROGRESS_FILENAME}.next`,
    DELTA20_RUNTIME_PUBLICATION_RECOVERY_FILENAME,
    DELTA20_RUNTIME_ROOT_TEARDOWN_PROGRESS_FILENAME,
  ]);
  const canonicalRoot =
    canonicalTempRootIdentity(tempRoot).canonical_temp_root;
  for (const filename of readdirSync(canonicalRoot)) {
    if (!allowed.has(filename)) {
      fail("SELF_TEST_DELTA20_PUBLICATION_UNEXPECTED_ARTIFACT");
    }
    const artifactPath = path.join(canonicalRoot, filename);
    validateMode0600RegularFile(
      artifactPath,
      "SELF_TEST_DELTA20_PUBLICATION_CLEANUP_ARTIFACT",
    );
    unlinkSync(artifactPath);
    fsyncExactDirectory(canonicalRoot);
  }
  if (readdirSync(canonicalRoot).length !== 0) {
    fail("SELF_TEST_DELTA20_PUBLICATION_ROOT_NOT_EMPTY");
  }
  rmdirSync(canonicalRoot);
  fsyncExactDirectory(realpathSync.native(tmpdir()));
  if (!pathIsAbsent(canonicalRoot)) {
    fail("SELF_TEST_DELTA20_PUBLICATION_ROOT_RESIDUE");
  }
}

function cleanupDelta20RuntimeRootTeardownSelfTestRoot(tempRoot) {
  if (!existsSync(tempRoot)) return;
  const canonicalRoot =
    canonicalTempRootIdentity(tempRoot).canonical_temp_root;
  const allowed = new Set([
    ...DELTA20_RUNTIME_ROOT_TEARDOWN_ORDER,
    DELTA20_RUNTIME_RETIREMENT_RECEIPT_FILENAME,
    DELTA20_RUNTIME_ROOT_TEARDOWN_PROGRESS_FILENAME,
    `${DELTA20_RUNTIME_ROOT_TEARDOWN_PROGRESS_FILENAME}.next`,
  ]);
  for (const filename of readdirSync(canonicalRoot)) {
    if (!allowed.has(filename)) {
      fail("SELF_TEST_DELTA20_RUNTIME_ROOT_TEARDOWN_UNEXPECTED_ARTIFACT");
    }
    const artifactPath = path.join(canonicalRoot, filename);
    validateMode0600RegularFile(
      artifactPath,
      "SELF_TEST_DELTA20_RUNTIME_ROOT_TEARDOWN_CLEANUP_ARTIFACT",
    );
    unlinkSync(artifactPath);
    fsyncExactDirectory(canonicalRoot);
  }
  rmdirSync(canonicalRoot);
  fsyncExactDirectory(realpathSync.native(tmpdir()));
}

