function protectedAccessStateFields(protectedAccessResult, budgets) {
  if (
    !protectedAccessResult ||
    typeof protectedAccessResult !== "object" ||
    ![
      "SELF_PROJECT_OIDC",
      "TEMPORARY_AUTOMATION_BYPASS",
    ].includes(protectedAccessResult.access_mode)
  ) {
    fail("PROTECTED_ACCESS_STATE_FIELDS");
  }
  return Object.freeze({
    access_mode: protectedAccessResult.access_mode,
    credential_lifecycle_contract:
      protectedAccessResult.credential_lifecycle_contract,
    project_bypass_prestate:
      protectedAccessResult.project_bypass_prestate,
    project_oidc_token_generations:
      budgets.used.projectOidcTokenGenerations,
    protection_access_handshake_gets:
      budgets.used.protectionAccessHandshakeGets,
    temporary_bypass_cycles: budgets.used.temporaryBypassCycles,
  });
}

async function continueHeaderQualificationPreview({
  retained,
  repositoryRoot,
  plan,
}) {
  const nextAttempt = retained.state.qualification_attempts + 1;
  const budgets = new GlobalBudgets(plan);
  seedCarriedBudgets(budgets, retained.state.budget_snapshot);
  const pushUrl = verifyRepositoryLivePreconditions(repositoryRoot, plan);
  verifyLocalExecutables();
  verifyStaticManifestSemantics(repositoryRoot);
  const context = delta11LiveContext({
    budgets,
    plan,
    pushUrl,
    repositoryRoot,
    tempRoot: retained.root,
  });
  Object.assign(context, {
    commitCreated: true,
    commitSha: retained.state.commit_sha,
    deploymentId: retained.state.deployment_id,
    remoteBranchCreated: true,
    branchRemoved: false,
    previewRemoved: false,
    statePath: retained.deploymentStatePath,
    worktreeRemoved: true,
    worktreeRemoveAttempted: true,
  });
  const resolved = resolveExactHeaderQualifiedPreview(
    context,
    retained.state,
    qualificationRetryAuthorityName(nextAttempt),
  );
  context.deploymentHostname = resolved.hostname;
  context.deploymentRecord = resolved.record;
  verifyRuntimeTemporaryBranchIdentity(context);
  validatePersistedDeploymentState(context);
  const protectedAccessResult = await performHeaderQualificationAttempt({
    attempt: nextAttempt,
    hostname: resolved.hostname,
    budgets,
  });
  const qualificationResult = protectedAccessResult.qualification_result;
  const state = validateHeaderQualificationState({
    ...retained.state,
    ...protectedAccessStateFields(protectedAccessResult, budgets),
    budget_snapshot: carriedBudgetSnapshot(budgets),
    qualification_attempts: nextAttempt,
    qualification_result: qualificationResult,
    target_binding: null,
  }, plan);
  rewriteHeaderQualificationState(retained.root, state, plan);
  failureEvidence = {
    cleanup_complete: "not_required",
    data_requests: 0,
    data_writes: "0",
    external_mutations: "occurred",
    runtime_requests: 0,
  };
  process.stdout.write(
    `PASS_ADMIN_V1_DELTA11_HEADER_QUALIFICATION preview_id=${state.deployment_id} disposition=${qualificationResult.disposition} qualification_attempts=${state.qualification_attempts} preview_creations=${state.preview_deployments_created} temporary_branch_pushes=${state.temporary_branch_create_pushes} application_requests=0 runtime_sessions=0 database_requests=0 data_writes=0 raw_headers_persisted=0 raw_bodies_persisted=0 raw_child_output_persisted=0\n`,
  );
}

async function createConditionalHeaderRepairPreview({
  retained,
  repositoryRoot,
  plan,
  modifiedPaths,
}) {
  if (
    retained.state.preview_deployments_created !== 1 ||
    retained.state.target_binding !== null ||
    modifiedPaths.length < 1 ||
    retained.state.qualification_attempts >= 4
  ) {
    fail("DELTA11_CONDITIONAL_REPAIR_STATE");
  }
  const budgets = new GlobalBudgets(plan);
  seedCarriedBudgets(budgets, retained.state.budget_snapshot);
  const inventoryAuthorities = conditionalRepairInventoryAuthorities(
    retained.state.qualification_attempts,
  );
  const pushUrl = verifyRepositoryLivePreconditions(repositoryRoot, plan);
  verifyLocalExecutables();
  verifyStaticManifestSemantics(repositoryRoot);
  const sourceContext = delta11LiveContext({
    budgets,
    plan,
    pushUrl,
    repositoryRoot,
    tempRoot: retained.root,
  });
  Object.assign(sourceContext, {
    commitCreated: true,
    commitSha: retained.state.commit_sha,
    deploymentId: retained.state.deployment_id,
    remoteBranchCreated: true,
    branchRemoved: false,
    previewRemoved: false,
    statePath: retained.deploymentStatePath,
    worktreeRemoved: true,
    worktreeRemoveAttempted: true,
  });
  const sourceResolved = resolveExactHeaderQualifiedPreview(
    sourceContext,
    retained.state,
    inventoryAuthorities.repairSource,
  );
  sourceContext.deploymentHostname = sourceResolved.hostname;
  sourceContext.deploymentRecord = sourceResolved.record;
  verifyRuntimeTemporaryBranchIdentity(sourceContext);
  validatePersistedDeploymentState(sourceContext);
  const repairCommitSha = createConditionalHeaderRepairCommit({
    budgets,
    priorCommitSha: retained.state.commit_sha,
    repositoryRoot,
    tempRoot: retained.root,
    modifiedPaths,
  });
  const repairTransaction = fastForwardConditionalRepairBranch({
    budgets,
    plan,
    priorCommitSha: retained.state.commit_sha,
    pushUrl,
    repairCommitSha,
    repositoryRoot,
  });
  const replacementContext = delta11LiveContext({
    budgets,
    plan,
    pushUrl,
    repositoryRoot,
    tempRoot: retained.root,
  });
  Object.assign(replacementContext, {
    branchTransactionJournal:
      retained.state.branch_transaction_journal.map((entry) => ({ ...entry })),
    commitCreated: true,
    commitSha: repairCommitSha,
    initialBranchAbsenceVerified: true,
    remoteBranchCreated: true,
    branchRemoved: false,
    previewRemoved: false,
    statePath: retained.deploymentStatePath,
    worktreeRemoved: true,
    worktreeRemoveAttempted: true,
  });
  const replacementResolved = await resolveUniquePreview(
    repairCommitSha,
    plan,
    budgets,
    replacementContext.inventorySince,
    inventoryAuthorities.replacementDiscovery,
  );
  budgets.take("previewDeploymentsCreated");
  verifyRuntimeTemporaryBranchIdentity(replacementContext);
  const github = githubAdvisoryCorroboration(
    repairCommitSha,
    plan,
    budgets,
  );
  const replacementIdentity = validateResolvedPreview(
    replacementResolved,
    repairCommitSha,
    plan,
    github,
  );
  replacementContext.deploymentId = replacementIdentity.deployment_id;
  replacementContext.deploymentHostname = replacementResolved.hostname;
  replacementContext.deploymentRecord = replacementResolved.record;
  await deleteAndVerifyPreview(
    sourceContext,
    inventoryAuthorities.supersededAbsence,
  );
  rewriteDeploymentState(
    retained.root,
    retained.deploymentStatePath,
    replacementContext.deploymentId,
    repairCommitSha,
  );
  const nextAttempt = retained.state.qualification_attempts + 1;
  const protectedAccessResult = await performHeaderQualificationAttempt({
    attempt: nextAttempt,
    hostname: replacementResolved.hostname,
    budgets,
  });
  const qualificationResult = protectedAccessResult.qualification_result;
  const state = validateHeaderQualificationState({
    ...retained.state,
    ...protectedAccessStateFields(protectedAccessResult, budgets),
    branch_repair_transaction: repairTransaction,
    budget_snapshot: carriedBudgetSnapshot(budgets),
    commit_sha: repairCommitSha,
    deployment_id: replacementContext.deploymentId,
    preview_deployments_created: 2,
    qualification_attempts: nextAttempt,
    qualification_result: qualificationResult,
    target_binding: null,
    temporary_branch_create_pushes: 2,
  }, plan);
  rewriteHeaderQualificationState(retained.root, state, plan);
  failureEvidence = {
    cleanup_complete: "superseded_preview_removed",
    data_requests: 0,
    data_writes: "0",
    external_mutations: "occurred",
    runtime_requests: 0,
  };
  process.stdout.write(
    `PASS_ADMIN_V1_DELTA11_HEADER_QUALIFICATION preview_id=${state.deployment_id} disposition=${qualificationResult.disposition} qualification_attempts=${state.qualification_attempts} preview_creations=2 superseded_preview_remaining=0 temporary_branch_pushes=2 application_requests=0 runtime_sessions=0 database_requests=0 data_writes=0 raw_headers_persisted=0 raw_bodies_persisted=0 raw_child_output_persisted=0\n`,
  );
}

async function recoverDelta15AuthQualification({
  plan,
  repositoryRoot,
  retained,
}) {
  const budgets = new GlobalBudgets(plan);
  seedDelta15QualificationRecoveryKnownBudgets(budgets);
  const pushUrl = verifyRepositoryLivePreconditions(repositoryRoot, plan);
  verifyLocalExecutables();
  verifyStaticManifestSemantics(repositoryRoot);
  const candidateManifest = completeDelta14AuthorizedPathManifest(
    repositoryRoot,
    plan,
  );
  const commits = validateDelta15RecoveredCommitPair({
    activationCommitSha: retained.state.commit_sha,
    candidateManifest,
    plan,
    repositoryRoot,
  });
  const context = delta11LiveContext({
    budgets,
    plan,
    pushUrl,
    repositoryRoot,
    tempRoot: retained.root,
  });
  Object.assign(context, {
    commitCreated: true,
    commitSha: commits.activation_commit_sha,
    deploymentId: retained.state.deployment_id,
    initialBranchAbsenceVerified: true,
    previewRemoved: false,
    remoteBranchCreated: false,
    branchRemoved: true,
    statePath: retained.deploymentStatePath,
    worktreeRemoved: true,
    worktreeRemoveAttempted: true,
  });
  const executionLock = acquireResumeExecutionLock();
  let executionLockReleased = false;
  let adminPasswordBytes = null;
  let qualificationDirect = null;
  let fixtureRows = null;
  let dataCleaned = true;
  try {
    verifyVercelProject(budgets);
    const resolved = resolveExactHeaderQualifiedPreview(
      context,
      {
        branch: plan.branch,
        commit_sha: commits.activation_commit_sha,
        deployment_id: retained.state.deployment_id,
      },
      "delta15QualificationRecovery",
    );
    context.deploymentHostname = resolved.hostname;
    context.deploymentRecord = resolved.record;
    validateDelta15RecoveryPhasePreviewOrdinal(
      resolved.inventory,
      {
        branch: plan.branch,
        commit_sha: commits.activation_commit_sha,
        deployment_id: retained.state.deployment_id,
      },
      plan,
    );
    if (
      resolved.inventory.some((record) =>
        inventoryGitMatches(record, commits.registration_commit_sha, plan),
      )
    ) {
      fail("DELTA15_QUALIFICATION_RECOVERY_REGISTRATION_DEPLOYMENT");
    }
    validatePersistedDeploymentState(context);
    const branchAbsence = verifyDelta15TemporaryBranchAbsentTwice(
      context,
      "DELTA15_QUALIFICATION_RECOVERY_BRANCH_ABSENCE",
    );
    const environmentFirst = captureDelta13EnvironmentSnapshot(
      budgets,
      "DELTA15_QUALIFICATION_RECOVERY_ENVIRONMENT_FIRST",
    );
    const environmentSecond = captureDelta13EnvironmentSnapshot(
      budgets,
      "DELTA15_QUALIFICATION_RECOVERY_ENVIRONMENT_SECOND",
    );
    assertDelta13EnvironmentRestored(
      environmentFirst,
      environmentSecond,
      "DELTA15_QUALIFICATION_RECOVERY_ENVIRONMENT_STABILITY",
    );
    adminPasswordBytes = readProtectedDelta13AdminPassword(
      repositoryRoot,
      budgets,
    );
    const qualificationEnvironment =
      readProtectedDelta15QualificationEnvironment(
        repositoryRoot,
        budgets,
        adminPasswordBytes,
      );
    const qualificationBudgets = new Delta15QualificationBudgets();
    qualificationDirect = await createCountedSupabase(
      qualificationEnvironment.environment,
      qualificationEnvironment.confirmedOrigin,
      qualificationBudgets,
    );
    const fixtureState = Object.freeze({
      markCleaned() {
        dataCleaned = true;
        fixtureRows = null;
      },
      setRows(rows) {
        if (!Array.isArray(rows) || rows.length !== 3) {
          fail("DELTA15_QUALIFICATION_RECOVERY_FIXTURE_ROWS");
        }
        dataCleaned = false;
        fixtureRows = rows;
      },
    });
    const qualification = await performDelta13AuthQualificationAttempt({
      adminPasswordBytes,
      attempt: 2,
      budgets,
      cleanupIdentity: {
        commit_sha: commits.activation_commit_sha,
        deployment_id: retained.state.deployment_id,
      },
      direct: qualificationDirect,
      fixtureState,
      hostname: resolved.hostname,
      plan,
      qualificationBudgets,
      qualificationEnvironment,
      runMarker: randomUUID(),
      tempRoot: retained.root,
    });
    if (
      qualification?.qualification_result?.ready !== true ||
      !protectedAccessCleanupComplete() ||
      dataCleaned !== true ||
      fixtureRows !== null ||
      qualification.qualification_result.exact_fixture_rows_remaining !== 0
    ) {
      fail("DELTA15_QUALIFICATION_RECOVERY_NOT_READY");
    }
    const directCounts = qualificationDirect.counts();
    const completion = validateDelta15QualificationCompletion({
      current_direct_requests: directCounts.directTotal,
      prior_direct_requests: 3,
      qualification_cycles: budgets.used.authQualificationCycles,
      qualification_requests: budgets.used.authQualificationRequests,
      recovered: true,
    });
    const qualificationRecovery = validateDelta15QualificationRecovery({
      activation_candidate_divergence:
        commits.activation_candidate_divergence,
      branch_absence_checks: branchAbsence.absence_checks,
      control_point:
        "AFTER_REQUEST_6_AND_FIXTURE_CLEANUP_BEFORE_STATE_WRITE",
      environment_absence_snapshots: 2,
      historical_branch_delete_pushes: "ONE_OR_TWO_CONFIRMED_ABSENT",
      historical_read_counters_restarted: true,
      prior_application_requests: 6,
      prior_direct_requests: 3,
      prior_error_code: "DELTA15_QUALIFICATION_DIRECT_COUNTS",
      prior_fixture_rows_remaining: 0,
      prior_runtime_sessions: 0,
      recovery_application_requests: 6,
      recovery_direct_requests: directCounts.directTotal,
      registration_current_inventory_absent: true,
      resource_counts: {
        environment_records_created: 2,
        environment_records_remaining: 0,
        official_application_requests: 0,
        phase_preview_creations_total: 3,
        temporary_branch_create_pushes: 2,
        temporary_commits_created: 2,
        transaction_preview_creations: 1,
      },
    }, completion);
    const authFixtureQualificationEvidenceSha256 = sha256(
      canonicalJson({
        qualification_recovery: qualificationRecovery,
        qualification_result: qualification.qualification_result,
      }),
    );
    const environmentOverrideCleanupEvidenceSha256 = sha256(
      canonicalJson({
        branch_override_absence_checks: 2,
        exact_records_remaining: 0,
        global_preview_metadata_restored: true,
        recovery: true,
      }),
    );
    const branchCleanupEvidenceSha256 = sha256(
      canonicalJson({
        activation_commit_sha: commits.activation_commit_sha,
        absence_checks: branchAbsence.absence_checks,
        branch: plan.branch,
        branch_remaining: branchAbsence.branch_remaining,
        recovery: true,
      }),
    );
    const registrationZeroDeploymentEvidenceSha256 = sha256(
      canonicalJson({
        activation_commit_sha: commits.activation_commit_sha,
        control_point_passed: true,
        current_inventory_absence: true,
        prior_error_code: "DELTA15_QUALIFICATION_DIRECT_COUNTS",
        registration_commit_sha: commits.registration_commit_sha,
        registration_inventory_traversals: 4,
      }),
    );
    const state = validateDelta13AuthState({
      access_mode: qualification.access_mode,
      activation_commit_sha: commits.activation_commit_sha,
      activation_push_transaction: null,
      alternate_index_removed: true,
      auth_fixture_qualification_evidence_sha256:
        authFixtureQualificationEvidenceSha256,
      branch: plan.branch,
      branch_cleanup_evidence_sha256: branchCleanupEvidenceSha256,
      branch_transaction_journal: [],
      budget_snapshot: delta13BudgetSnapshot(budgets),
      commit_sha: commits.activation_commit_sha,
      credential_lifecycle_contract:
        qualification.credential_lifecycle_contract,
      deployment_after_environment_records: true,
      deployment_id: retained.state.deployment_id,
      environment_after: environmentSecond,
      environment_before: environmentFirst,
      environment_override_cleanup_evidence_sha256:
        environmentOverrideCleanupEvidenceSha256,
      environment_records_removed: true,
      environment_transition: null,
      marker_sha256: plan.marker.sha256,
      official_runtime_attempt_started: false,
      phase: "34IA-34IZ-DELTA15",
      phase_preview_creations_total: 3,
      preview_deployments_created: 1,
      project_bypass_prestate: qualification.project_bypass_prestate,
      qualification_cycles: completion.qualification_cycles,
      qualification_direct_requests: completion.total_direct_requests,
      qualification_recovery: qualificationRecovery,
      qualification_requests: completion.qualification_requests,
      qualification_result: qualification.qualification_result,
      registration_commit_sha: commits.registration_commit_sha,
      registration_vercel_json_sha256:
        commits.registration_vercel_json_sha256,
      registration_zero_deployment_evidence_sha256:
        registrationZeroDeploymentEvidenceSha256,
      registration_zero_deployment_inventory_traversals: 4,
      registration_post_activation_inventory_checks: null,
      schema_version: 6,
      target_binding: null,
      temporary_branch_removed: true,
      temporary_branch_create_pushes: 2,
      worktree_removed: true,
    }, plan);
    writeDelta13AuthState(retained.root, state, plan);
    releaseResumeExecutionLock(executionLock);
    executionLockReleased = true;
    qualificationDirect = null;
    adminPasswordBytes.fill(0);
    adminPasswordBytes = null;
    failureEvidence = {
      cleanup_complete: "qualification_rows_zero_preview_retained",
      data_requests: completion.total_direct_requests,
      data_writes: "0",
      external_mutations: "qualification_rows_cleaned",
      runtime_requests: 0,
    };
    process.stdout.write(
      `PASS_ADMIN_V1_DELTA15_AUTH_FIXTURE_QUALIFICATION_RECOVERY preview_id=${state.deployment_id} access_mode=${state.access_mode} recovery_cycle=2 qualification_cycles=2 qualification_requests=12 preview_creations_total=3 environment_records_remaining=0 branch_remaining=0 database_requests=${state.qualification_direct_requests} qualification_fixture_rows_remaining=0 runtime_sessions=0 official_application_requests=0 raw_headers_persisted=0 raw_bodies_persisted=0 raw_values_persisted=0 secret_hashes_persisted=0 raw_child_output_persisted=0\n`,
    );
  } catch (caught) {
    const originalCode = categoricalErrorCode(caught);
    if (
      !executionLockReleased &&
      budgets.used.authQualificationRequests <= 6
    ) {
      releaseResumeExecutionLock(executionLock);
      executionLockReleased = true;
    }
    const attemptLockPreserved =
      budgets.used.authQualificationRequests > 6;
    failureEvidence = {
      cleanup_complete:
        dataCleaned && fixtureRows === null
          ? attemptLockPreserved
            ? "qualification_rows_zero_preview_retained_attempt_lock_preserved"
            : "qualification_rows_zero_preview_retained"
          : "false",
      data_requests: qualificationDirect?.counts().directTotal ?? 0,
      data_writes:
        dataCleaned && fixtureRows === null ? "0" : "possible_or_occurred",
      external_mutations: "qualification_only_preview_retained",
      runtime_requests: 0,
    };
    fail(originalCode);
  } finally {
    if (adminPasswordBytes) adminPasswordBytes.fill(0);
  }
}

async function cleanupDelta17AFailedQualification({
  context,
  hooks = {},
  plan,
  qualificationBudgets,
  tempRoot,
}) {
  const emergencyCleanup =
    hooks.emergencyDataCleanup ?? emergencyDataCleanup;
  const fullCleanup = hooks.cleanupFixtures ?? cleanupFixtures;
  if (
    typeof emergencyCleanup !== "function" ||
    typeof fullCleanup !== "function"
  ) {
    fail("DELTA17A_FAILED_QUALIFICATION_CLEANUP_HOOKS");
  }
  if (context?.dataCleaned === true) return true;
  if (!context?.direct) return false;
  if (!context.runtime || !context.fixtures) {
    if (!context.fixtureRows) {
      const lastAttemptedOrdinal =
        context.runtimeState?.lastAttemptedOrdinal ?? 0;
      if (
        !Number.isInteger(lastAttemptedOrdinal) ||
        lastAttemptedOrdinal < 0 ||
        lastAttemptedOrdinal > 5
      ) {
        return false;
      }
      context.dataCleaned = true;
      return true;
    }
    context.cleanupDataBudgets = qualificationBudgets;
    await emergencyCleanup(context);
    return context.dataCleaned === true;
  }
  const verifiedLogoIdentity =
    hasVerifiedLogoCleanupIdentity(context.runtime);
  if (!verifiedLogoIdentity) {
    context.cleanupDataBudgets = qualificationBudgets;
    await emergencyCleanup(context);
    if (context.dataCleaned === true) {
      context.fixtureRows = null;
      const unverifiedLocatorPath = delta17CleanupLocatorPath(tempRoot);
      if (existsSync(unverifiedLocatorPath)) {
        removeDelta17CleanupLocators({ tempRoot });
      }
      context.runtime.cleanupLocator = null;
      context.runtime.cleanupLocatorPath = null;
    }
    return context.dataCleaned === true;
  }
  const verifiedStoragePath = canonicalLogoObjectPath(
    context.runtime.logoObjectPath,
  );
  if (!verifiedStoragePath) {
    fail("DELTA17A_FAILED_QUALIFICATION_STORAGE_LOCATOR");
  }
  if (!context.runtime.cleanupLocator) {
    const cleanupLocator = buildDelta17CleanupLocators({
      cleanupIdentity: {
        commit_sha: context.commitSha,
        deployment_id: context.deploymentId,
      },
      fixtures: context.fixtures,
      observedTools: [],
      plan,
      runtime: {
        ...context.runtime,
        logoObjectPath: verifiedStoragePath,
      },
    });
    persistDelta17CleanupLocators({
      locator: cleanupLocator,
      plan,
      tempRoot,
    });
    context.runtime.cleanupLocator = cleanupLocator;
    context.runtime.cleanupLocatorPath =
      delta17CleanupLocatorPath(tempRoot);
  }
  if (
    context.runtime.cleanupLocator.storage_path !== verifiedStoragePath
  ) {
    fail("DELTA17A_FAILED_QUALIFICATION_LOCATOR_IDENTITY");
  }
  await fullCleanup({
    budgets: qualificationBudgets,
    cleanupLocator: context.runtime.cleanupLocator,
    direct: context.direct,
    fixtures: context.fixtures,
    plan,
    progress: context.cleanupProgress,
    runtime: context.runtime,
  });
  context.dataCleaned = true;
  context.fixtureRows = null;
  removeDelta17CleanupLocators({ tempRoot });
  context.runtime.cleanupLocator = null;
  context.runtime.cleanupLocatorPath = null;
  return true;
}

