function delta20QualificationRecoveryBudgetSnapshot(recovery) {
  const plan = createRuntimePlan();
  const probe = new GlobalBudgets(plan);
  seedDelta13Budgets(probe, recovery.budget_snapshot);
  const stageIndex = DELTA20_QUALIFICATION_EXECUTION_STAGES.indexOf(
    recovery.stage,
  );
  const reserveAtLeast = (name, amount) => {
    if (amount > probe.limits[name]) {
      fail("DELTA20_QUALIFICATION_RECOVERY_BUDGET_RESERVE");
    }
    probe.used[name] = Math.max(probe.used[name], amount);
  };
  if (stageIndex >= 3) {
    reserveAtLeast("temporaryCommitsCreated", 1);
    reserveAtLeast("temporaryBranchCreatePushes", 1);
  }
  if (stageIndex >= 5) {
    reserveAtLeast(
      "environmentRecordCreateRequests",
      Object.keys(DELTA13_ENVIRONMENT_COMMENTS).length,
    );
  }
  if (stageIndex >= 7) {
    reserveAtLeast("temporaryCommitsCreated", 2);
    reserveAtLeast("markerFilesCreated", 1);
    reserveAtLeast("temporaryBranchCreatePushes", 2);
  }
  if (stageIndex >= 7) {
    reserveAtLeast("previewDeploymentsCreated", 1);
  }
  if (stageIndex >= 10) {
    reserveAtLeast("authQualificationCycles", 1);
    reserveAtLeast("authQualificationRequests", 6);
    reserveAtLeast("loginAttempts", 1);
    reserveAtLeast("projectOidcTokenGenerations", 1);
  }
  return Object.freeze({ ...probe.used });
}

function recordDelta20RecoveredOwnedBranch(context) {
  for (const details of [
    {
      attempt: 0,
      client_exit_class: "NOT_SENT",
      exact_ref_state: "ABSENT",
      external_mutation_possible: false,
      live_may_continue: true,
      operation: "CREATE",
      retry_permitted: false,
      state: "INITIAL_REF_ABSENT",
    },
    {
      attempt: 1,
      client_exit_class: "NOT_SENT",
      exact_ref_state: "NOT_READ",
      external_mutation_possible: true,
      live_may_continue: false,
      operation: "CREATE",
      retry_permitted: false,
      state: "CREATE_REQUESTED",
    },
    {
      attempt: 1,
      client_exit_class: "NOT_OBSERVED",
      exact_ref_state: "NOT_READ",
      external_mutation_possible: true,
      live_may_continue: false,
      operation: "CREATE",
      retry_permitted: false,
      state: "CREATE_RESULT_OBSERVED",
    },
    {
      attempt: 1,
      client_exit_class: "NOT_OBSERVED",
      exact_ref_state: "OURS",
      external_mutation_possible: true,
      live_may_continue: false,
      operation: "CREATE",
      retry_permitted: false,
      state: "CREATE_REF_OURS",
    },
    {
      attempt: 1,
      client_exit_class: "NOT_OBSERVED",
      exact_ref_state: "OURS",
      external_mutation_possible: true,
      live_may_continue: true,
      operation: "CREATE",
      retry_permitted: false,
      state: "CREATE_CONFIRMED",
    },
  ]) {
    recordBranchTransaction(context, details);
  }
}

function classifyDelta20InterruptedQualificationBranch(
  context,
  recovery,
  dependencies = {},
) {
  const readRegistrationState =
    dependencies.readRegistrationState ??
    ((candidateContext, candidateRecovery) =>
      readExactTemporaryBranchState(
        candidateContext,
        candidateRecovery.registration_commit_sha,
        "DELTA20_QUALIFICATION_RECOVERY_BRANCH",
      ));
  const readActivationState =
    dependencies.readActivationState ??
    ((candidateContext, candidateRecovery) =>
      readDelta14ActivationBranchState(
        candidateContext,
        candidateRecovery.registration_commit_sha,
        candidateRecovery.activation_commit_sha,
        "DELTA20_QUALIFICATION_RECOVERY_ACTIVATION_BRANCH",
      ));
  if (
    !dependencies ||
    typeof dependencies !== "object" ||
    Array.isArray(dependencies) ||
    Object.keys(dependencies).some(
      (key) =>
        !["readActivationState", "readRegistrationState"].includes(key),
    ) ||
    typeof readRegistrationState !== "function" ||
    typeof readActivationState !== "function"
  ) {
    fail("DELTA20_QUALIFICATION_RECOVERY_BRANCH_DEPENDENCIES");
  }
  if (recovery.registration_commit_sha === null) {
    return Object.freeze({
      conflict_preserved: false,
      owned_commit_sha: null,
      state: "ABSENT",
    });
  }
  const readState = recovery.activation_commit_sha === null
    ? () => readRegistrationState(context, recovery)
    : () => readActivationState(context, recovery);
  const observations = [readState(), readState()];
  if (
    observations.some((state) => state === "MALFORMED") ||
    observations[0] !== observations[1]
  ) {
    fail("DELTA20_QUALIFICATION_RECOVERY_BRANCH_UNSTABLE");
  }
  const state = observations[0];
  if (state === "OTHER") {
    return Object.freeze({
      conflict_preserved: true,
      owned_commit_sha: null,
      state,
    });
  }
  if (state === "ABSENT") {
    return Object.freeze({
      conflict_preserved: false,
      owned_commit_sha: null,
      state,
    });
  }
  const ownedCommitSha = state === "ACTIVATION"
    ? recovery.activation_commit_sha
    : state === "REGISTRATION" || state === "OURS"
      ? recovery.registration_commit_sha
      : null;
  if (ownedCommitSha === null) {
    fail("DELTA20_QUALIFICATION_RECOVERY_BRANCH_STATE");
  }
  return Object.freeze({
    conflict_preserved: false,
    owned_commit_sha: ownedCommitSha,
    state,
  });
}

async function waitDelta20InterruptedQualificationMutationWindow({
  plan,
  recovery,
  tempRoot,
}) {
  const locatorPath = path.join(
    canonicalTempRootIdentity(tempRoot).canonical_temp_root,
    DELTA18_INCREMENTAL_LOCATOR_FILENAME,
  );
  if (!existsSync(locatorPath)) return null;
  const locator = readDelta20RuntimeRecoveryLocator(locatorPath, plan);
  if (
    recovery.run_marker === null ||
    locator.run_marker !== recovery.run_marker ||
    locator.commit_sha !== recovery.activation_commit_sha ||
    locator.deployment_id !== recovery.deployment_id ||
    locator.user_agent !==
      `AiFinder-Phase-34IA-Delta18-Qualification-${recovery.run_marker}`
  ) {
    fail("DELTA20_QUALIFICATION_RECOVERY_LOCATOR_BINDING");
  }
  if (locator.logout_mutation_window_end !== null) {
    const closesAt = Date.parse(locator.logout_mutation_window_end);
    const remaining = closesAt - Date.now();
    if (
      !Number.isFinite(closesAt) ||
      remaining > DELTA18_QUALIFICATION_LOGOUT_MUTATION_WINDOW_MS
    ) {
      fail("DELTA20_QUALIFICATION_RECOVERY_MUTATION_WINDOW");
    }
    if (remaining > 0) {
      await new Promise((resolve) => setTimeout(resolve, remaining));
    }
  }
  return locator;
}

function removeDelta20InterruptedQualificationDeploymentState(
  retained,
  recovery,
) {
  const statePath = path.join(retained.root, DEPLOYMENT_STATE_FILENAME);
  if (!existsSync(statePath)) return;
  const state = readDeploymentStateValue(retained.root);
  if (
    recovery.activation_commit_sha === null ||
    state.commit_sha !== recovery.activation_commit_sha ||
    (recovery.deployment_id !== null &&
      state.deployment_id !== recovery.deployment_id)
  ) {
    fail("DELTA20_QUALIFICATION_RECOVERY_DEPLOYMENT_REMOVE_BINDING");
  }
  unlinkSync(statePath);
  fsyncExactDirectory(retained.root);
  if (existsSync(statePath)) {
    fail("DELTA20_QUALIFICATION_RECOVERY_DEPLOYMENT_RESIDUE");
  }
}

function finishDelta20InterruptedQualificationLocalArtifacts({
  plan,
  recovery,
  retained,
}) {
  const indexPath = path.join(
    retained.root,
    DELTA14_ALTERNATE_INDEX_FILENAME,
  );
  if (existsSync(indexPath) || existsSync(`${indexPath}.lock`)) {
    removeDelta14AlternateIndex(retained.root, indexPath);
  }
  const transitionPath = path.join(
    retained.root,
    DELTA18_BRANCH_TRANSITION_FILENAME,
  );
  if (existsSync(transitionPath)) {
    const bytes = readRegularFile(transitionPath, {
      mode: 0o600,
      maximum: 16 * 1024,
    });
    try {
      const transition = validateDelta14ActivationTransition(
        parseJsonBuffer(
          bytes,
          "DELTA20_QUALIFICATION_RECOVERY_TRANSITION_REMOVE",
        ),
        plan,
      );
      if (
        transition.registration_commit_sha !==
          recovery.registration_commit_sha ||
        transition.activation_commit_sha !== recovery.activation_commit_sha
      ) {
        fail("DELTA20_QUALIFICATION_RECOVERY_TRANSITION_REMOVE_BINDING");
      }
    } finally {
      bytes.fill(0);
    }
    unlinkSync(transitionPath);
    fsyncExactDirectory(retained.root);
  }
  removeDelta18DurableEvidenceFiles(retained.root);
  removeDelta20InterruptedQualificationDeploymentState(retained, recovery);
  const scrubContext = {
    tempRoot: retained.root,
    tempSecretsRemoved: false,
  };
  scrubExternalTempSecrets(scrubContext);
  if (scrubContext.tempSecretsRemoved !== true) {
    fail("DELTA20_QUALIFICATION_RECOVERY_SECRET_RESIDUE");
  }
  reconcileKnownDelta20AtomicArtifacts(retained.root, plan);
  if (
    canonicalJson(readdirSync(retained.root).sort()) !==
      canonicalJson([DELTA20_QUALIFICATION_EXECUTION_RECOVERY_FILENAME])
  ) {
    fail("DELTA20_QUALIFICATION_RECOVERY_LOCAL_RESIDUE");
  }
}

async function repairDelta20InterruptedQualificationExecution({
  plan,
  pushUrl,
  repositoryRoot,
  retained,
}) {
  let recovery = readDelta20QualificationExecutionRecovery(retained.root);
  const activeState = delta20RetainedActiveAuthorizationState();
  if (activeState === "ACTIVE") {
    if (
      recovery.stage !== "INITIALIZED" ||
      recovery.state !== "EXECUTION_IN_PROGRESS" ||
      readdirSync(retained.root).some(
        (entry) =>
          entry !== DELTA20_QUALIFICATION_EXECUTION_RECOVERY_FILENAME,
      )
    ) {
      fail("DELTA20_QUALIFICATION_RECOVERY_UNCONSUMED_STATE");
    }
    validateDelta20RetainedAuthorizationArtifacts({
      expectedActiveState: "ACTIVE",
      expectedCandidateManifestSha256:
        recovery.candidate_manifest_sha256,
    });
    const lock = acquireDelta20ExecutionLock(
      retained.root,
      realpathSync.native(tmpdir()),
      "ACTIVE",
    );
    removeDelta20QualificationExecutionRecovery(retained.root);
    rmdirSync(retained.root);
    fsyncExactDirectory(realpathSync.native(tmpdir()));
    releaseDelta20ExecutionLock(lock);
    failureEvidence = {
      cleanup_complete: "true",
      data_requests: 0,
      data_writes: "0",
      external_mutations: "0",
      runtime_requests: 0,
    };
    process.stdout.write(
      "PASS_ADMIN_V1_DELTA20_INTERRUPTED_QUALIFICATION_CLEANUP attempt_spent=false cleanup_complete=true external_mutations=0 failures=0 internal_failures=0\n",
    );
    return;
  }
  validateDelta20RetainedAuthorizationArtifacts({
    expectedActiveState: "QUALIFICATION_ATTEMPT_STARTED",
    expectedCandidateManifestSha256:
      recovery.candidate_manifest_sha256,
    expectedQualificationTempRootBasename: path.basename(retained.root),
  });
  const executionLock = acquireDelta20ExecutionLock(retained.root);
  let executionLockReleased = false;
  let adminPasswordBytes = null;
  try {
    if (recovery.state === "ABORTED_CLEANUP_COMPLETE") {
      finishDelta20InterruptedQualificationLocalArtifacts({
        plan,
        recovery,
        retained,
      });
      releaseDelta20ExecutionLock(executionLock);
      executionLockReleased = true;
      failureEvidence = {
        cleanup_complete: "true",
        data_requests: 0,
        data_writes: "0",
        external_mutations: "0",
        runtime_requests: 0,
      };
      process.stdout.write(
        "PASS_ADMIN_V1_DELTA20_INTERRUPTED_QUALIFICATION_CLEANUP already_complete=true attempt_spent=true cleanup_complete=true failures=0 internal_failures=0\n",
      );
      return;
    }
    await waitDelta20MutationQuiescence({
      intents: recovery.mutation_intents,
    });
    const budgets = new GlobalBudgets(plan);
    seedDelta13Budgets(
      budgets,
      delta20QualificationRecoveryBudgetSnapshot(recovery),
    );
    const context = delta11LiveContext({
      budgets,
      plan,
      pushUrl,
      repositoryRoot,
      tempRoot: retained.root,
    });
    Object.assign(context, {
      branchDeleteAttempts: recovery.cleanup_branch_delete_intents,
      deferTempRootRemoval: true,
      inventorySince:
        recovery.execution_started_at_epoch_ms -
        VERCEL_INVENTORY_CLOCK_SKEW_MS,
      registrationCommitSha: recovery.registration_commit_sha,
      activationCommitSha: recovery.activation_commit_sha,
      statePath: retained.deploymentStatePath,
      tempSecretsRemoved: true,
      previewDeleteAttempts: recovery.cleanup_preview_delete_intents,
      preservePreviewDeleteAttempts: true,
      worktreeRemoved: true,
      worktreeRemoveAttempted: true,
    });
    context.onBranchDeleteMutationIntent = ({ attempt }) => {
      if (attempt !== recovery.cleanup_branch_delete_intents + 1) {
        fail("DELTA20_QUALIFICATION_RECOVERY_BRANCH_INTENT_SEQUENCE");
      }
      recovery = appendDelta20QualificationMutationIntent({
        kind: "BRANCH_DELETE",
        recovery,
        tempRoot: retained.root,
      });
      recovery = persistDelta20QualificationExecutionRecovery(
        retained.root,
        {
          ...recovery,
          budget_snapshot: delta20ProjectedBudgetSnapshot(budgets, {
            temporaryBranchDeletePushes: 1,
          }),
          cleanup_branch_delete_intents: attempt,
        },
      ).value;
    };
    context.onPreviewDeleteMutationIntent = ({ attempt }) => {
      if (attempt !== recovery.cleanup_preview_delete_intents + 1) {
        fail("DELTA20_QUALIFICATION_RECOVERY_PREVIEW_INTENT_SEQUENCE");
      }
      recovery = appendDelta20QualificationMutationIntent({
        kind: "PREVIEW_DELETE",
        recovery,
        tempRoot: retained.root,
      });
      recovery = persistDelta20QualificationExecutionRecovery(
        retained.root,
        {
          ...recovery,
          budget_snapshot: delta20ProjectedBudgetSnapshot(budgets, {
            vercelControlInvocations: 1,
            vercelDirectDeleteAttempts: 1,
          }),
          cleanup_preview_delete_intents: attempt,
        },
      ).value;
    };
    const branch = classifyDelta20InterruptedQualificationBranch(
      context,
      recovery,
    );
    const indexPath = path.join(
      retained.root,
      DELTA14_ALTERNATE_INDEX_FILENAME,
    );
    if (existsSync(indexPath) || existsSync(`${indexPath}.lock`)) {
      removeDelta14AlternateIndex(retained.root, indexPath);
    }
    verifyVercelProject(budgets);
    const previewCommitSha = recovery.activation_commit_sha ??
      recovery.registration_commit_sha;
    const combinedBranchCleanup =
      branch.owned_commit_sha !== null &&
      branch.owned_commit_sha === previewCommitSha;
    if (previewCommitSha !== null) {
      context.commitSha = previewCommitSha;
      context.activationPreviewMayExist = true;
      context.remoteBranchCreated = combinedBranchCleanup;
      context.branchRemoved = !combinedBranchCleanup;
      if (combinedBranchCleanup) {
        context.branchTransactionJournal = [];
        recordDelta20RecoveredOwnedBranch(context);
      }
      context.previewRemoved = false;
      if (retained.deploymentStatePath !== null) {
        const deploymentState = readDeploymentStateValue(retained.root);
        context.deploymentId = deploymentState.deployment_id;
        try {
          const resolved = resolveExactHeaderQualifiedPreview(
            context,
            {
              branch: plan.branch,
              commit_sha: deploymentState.commit_sha,
              deployment_id: deploymentState.deployment_id,
            },
            "runtimeIdentity",
          );
          context.deploymentHostname = resolved.hostname;
          context.deploymentRecord = resolved.record;
          validatePersistedDeploymentState(context);
        } catch {
          await verifyPreviewAbsent(context);
        }
      }
      const previewFailures = await cleanupResolvedExternalState(context);
      if (previewFailures.length !== 0 || !context.previewRemoved) {
        fail("DELTA20_QUALIFICATION_RECOVERY_PREVIEW_CLEANUP");
      }
      recovery = persistDelta20QualificationExecutionRecovery(
        retained.root,
        {
          ...recovery,
          budget_snapshot: delta13BudgetSnapshot(budgets),
        },
      ).value;
    } else {
      context.previewRemoved = true;
    }
    await waitDelta20InterruptedQualificationMutationWindow({
      plan,
      recovery,
      tempRoot: retained.root,
    });
    adminPasswordBytes = readProtectedDelta13AdminPassword(
      repositoryRoot,
      budgets,
    );
    const cleanupEnvironment = readProtectedDelta15QualificationEnvironment(
      repositoryRoot,
      budgets,
      adminPasswordBytes,
    );
    const priorBudgets = new Delta17APriorReconciliationBudgets();
    const direct = await createCountedSupabase(
      cleanupEnvironment.environment,
      cleanupEnvironment.confirmedOrigin,
      priorBudgets,
    );
    recovery = appendDelta20QualificationMutationIntent({
      kind: "PRIOR_RECONCILIATION",
      recovery,
      tempRoot: retained.root,
    });
    const prior = await reconcileDelta17APriorResidue({
      budgets: priorBudgets,
      direct,
    });
    if (
      prior.evidence.zero_residue !== true ||
      prior.evidence.ownership_ambiguity !== 0
    ) {
      fail("DELTA20_QUALIFICATION_RECOVERY_DATA_RESIDUE");
    }
    context.dataCleaned = true;
    const environmentCurrent = captureDelta13EnvironmentSnapshot(
      budgets,
      "DELTA20_QUALIFICATION_RECOVERY_ENVIRONMENT_CURRENT",
    );
    const cleanupIds = {};
    for (const name of Object.keys(DELTA13_ENVIRONMENT_COMMENTS)) {
      const currentId =
        environmentCurrent.records[name].phase_owned_record_id;
      const persistedId = recovery.environment_ids[name] ?? null;
      if (
        persistedId !== null &&
        currentId !== null &&
        persistedId !== currentId
      ) {
        fail("DELTA20_QUALIFICATION_RECOVERY_ENVIRONMENT_IDENTITY");
      }
      if (typeof currentId === "string") cleanupIds[name] = currentId;
    }
    if (
      recovery.environment_before === null &&
      Object.keys(cleanupIds).length !== 0
    ) {
      fail("DELTA20_QUALIFICATION_RECOVERY_ENVIRONMENT_WITHOUT_BASELINE");
    }
    if (Object.keys(cleanupIds).length !== 0) {
      recovery = persistDelta20QualificationExecutionRecovery(
        retained.root,
        {
          ...recovery,
          budget_snapshot: delta13BudgetSnapshot(budgets),
          environment_ids: { ...recovery.environment_ids, ...cleanupIds },
        },
      ).value;
      deleteDelta13EnvironmentRecords({
        before: environmentCurrent,
        budgets,
        context,
        ids: cleanupIds,
        onMutationIntent: ({ attempt, name }) => {
          if (
            attempt !==
              recovery.cleanup_environment_delete_intents[name] + 1
          ) {
            fail(
              "DELTA20_QUALIFICATION_RECOVERY_ENVIRONMENT_INTENT_SEQUENCE",
            );
          }
          recovery = appendDelta20QualificationMutationIntent({
            kind: "ENVIRONMENT_RECORD_DELETE",
            recovery,
            tempRoot: retained.root,
          });
          recovery = persistDelta20QualificationExecutionRecovery(
            retained.root,
            {
              ...recovery,
              budget_snapshot: delta20ProjectedBudgetSnapshot(budgets, {
                environmentRecordDeleteRequests: 1,
                vercelControlInvocations: 1,
              }),
              cleanup_environment_delete_intents: {
                ...recovery.cleanup_environment_delete_intents,
                [name]: attempt,
              },
            },
          ).value;
        },
        priorMutationIntents:
          recovery.cleanup_environment_delete_intents,
      });
    } else {
      const environmentSecond = captureDelta13EnvironmentSnapshot(
        budgets,
        "DELTA20_QUALIFICATION_RECOVERY_ENVIRONMENT_ABSENCE",
      );
      assertDelta13EnvironmentRestored(
        environmentCurrent,
        environmentSecond,
        "DELTA20_QUALIFICATION_RECOVERY_ENVIRONMENT_ABSENCE",
      );
    }
    recovery = persistDelta20QualificationExecutionRecovery(
      retained.root,
      {
        ...recovery,
        budget_snapshot: delta13BudgetSnapshot(budgets),
      },
    ).value;
    if (branch.owned_commit_sha !== null && !combinedBranchCleanup) {
      context.commitSha = branch.owned_commit_sha;
      context.branchTransactionJournal = [];
      context.branchDeleteAttempts =
        recovery.cleanup_branch_delete_intents;
      context.branchFinalAbsenceVerified = false;
      context.remoteBranchCreated = true;
      context.branchRemoved = false;
      recordDelta20RecoveredOwnedBranch(context);
      deleteTemporaryBranch(context);
    } else {
      context.branchRemoved = true;
    }
    if (!context.branchRemoved || !context.previewRemoved) {
      fail("DELTA20_QUALIFICATION_RECOVERY_EXTERNAL_RESIDUE");
    }
    const cleanupProofSha256 = sha256(canonicalJson({
      application_requests_replayed: 0,
      branch_conflict_preserved: branch.conflict_preserved,
      branch_remaining: 0,
      environment_records_remaining: 0,
      preview_remaining: 0,
      prior_reconciliation_evidence_sha256: prior.evidence_sha256,
      qualification_attempt_spent: true,
      request_replays: 0,
      zero_residue: true,
    }));
    recovery = persistDelta20QualificationExecutionRecovery(
      retained.root,
      {
        ...recovery,
        budget_snapshot: delta13BudgetSnapshot(budgets),
        cleanup_proof_sha256: cleanupProofSha256,
        prior_reconciliation_evidence_sha256: prior.evidence_sha256,
        state: "ABORTED_CLEANUP_COMPLETE",
      },
    ).value;
    finishDelta20InterruptedQualificationLocalArtifacts({
      plan,
      recovery,
      retained,
    });
    releaseDelta20ExecutionLock(executionLock);
    executionLockReleased = true;
    failureEvidence = {
      cleanup_complete: "true",
      data_requests: direct.counts().directTotal,
      data_writes: "0",
      external_mutations: "occurred_and_cleaned",
      runtime_requests: 0,
    };
    process.stdout.write(
      `PASS_ADMIN_V1_DELTA20_INTERRUPTED_QUALIFICATION_CLEANUP application_requests_replayed=0 request_replays=0 branch_conflict_preserved=${branch.conflict_preserved} attempt_spent=true cleanup_complete=true failures=0 internal_failures=0\n`,
    );
  } finally {
    if (adminPasswordBytes) adminPasswordBytes.fill(0);
    if (!executionLockReleased) {
      try {
        releaseDelta20ExecutionLock(executionLock);
      } catch {
        failureEvidence.cleanup_complete = "false";
      }
    }
  }
}

function finishDelta20InterruptedExecutionLocalArtifacts(retained, plan) {
  const markerPath = path.join(
    retained.root,
    RESUME_ATTEMPT_MARKER_FILENAME,
  );
  if (existsSync(markerPath)) {
    const marker = readDelta20RuntimeResumeAttemptMarker(
      retained.root,
      delta18OfficialRuntimeAttemptBinding({
        retained,
        targetSha256: retained.state.target_binding,
      }),
    );
    removeResumeAttemptMarker(marker);
  }
  const projectionPath = path.join(
    retained.root,
    DELTA17_OFFICIAL_PROJECTION_FILENAME,
  );
  if (existsSync(projectionPath)) {
    removeDelta17SanitizedPoststateProjection({
      kind: "OFFICIAL",
      tempRoot: retained.root,
    });
  }
  removeDelta18DurableEvidenceFiles(retained.root);
  const scrubContext = {
    tempRoot: retained.root,
    tempSecretsRemoved: false,
  };
  scrubExternalTempSecrets(scrubContext);
  if (scrubContext.tempSecretsRemoved !== true) {
    fail("DELTA20_INTERRUPTED_EXECUTION_SECRET_RESIDUE");
  }
  reconcileKnownDelta20AtomicArtifacts(retained.root, plan);
}

async function repairDelta20InterruptedRuntimeExecution({
  plan,
  pushUrl,
  repositoryRoot,
  retained,
}) {
  let recovery = readDelta20RuntimeExecutionRecovery(retained.root);
  const executionLock = acquireDelta20ExecutionLock(retained.root);
  let executionLockReleased = false;
  let adminPasswordBytes = null;
  try {
    if (recovery.state === "ABORTED_CLEANUP_COMPLETE") {
      finishDelta20InterruptedExecutionLocalArtifacts(retained, plan);
      releaseDelta20ExecutionLock(executionLock);
      executionLockReleased = true;
      failureEvidence = {
        cleanup_complete: "true",
        data_requests: 0,
        data_writes: "0",
        external_mutations: "0",
        runtime_requests: 0,
      };
      process.stdout.write(
        "PASS_ADMIN_V1_DELTA20_INTERRUPTED_RUNTIME_CLEANUP already_complete=true application_requests=0 runtime_sessions=0 attempt_spent=true cleanup_complete=true failures=0 internal_failures=0\n",
      );
      return;
    }
    if (!recovery.repair_started) {
      recovery = persistDelta20RuntimeExecutionRecovery(retained.root, {
        ...recovery,
        repair_started: true,
      }).value;
    }
    await waitDelta20MutationQuiescence({
      intents: recovery.mutation_intents,
    });
    const budgets = new GlobalBudgets(plan);
    seedDelta13Budgets(budgets, recovery.budget_snapshot);
    const context = delta11LiveContext({
      budgets,
      plan,
      pushUrl,
      repositoryRoot,
      tempRoot: retained.root,
    });
    Object.assign(context, {
      branchRemoved: true,
      branchTransactionJournal:
        retained.state.branch_transaction_journal.map((entry) => ({
          ...entry,
        })),
      commitCreated: true,
      commitSha: retained.state.commit_sha,
      deploymentId: retained.state.deployment_id,
      initialBranchAbsenceVerified: true,
      phaseOwnedRetainedPreviewId: retained.state.deployment_id,
      preservePreviewDeleteAttempts: true,
      previewDeleteAttempts: recovery.cleanup_preview_delete_intents,
      previewRemoved: false,
      remoteBranchCreated: false,
      resumeMode: true,
      statePath: retained.deploymentStatePath,
      tempSecretsRemoved: true,
      worktreeRemoved: true,
      worktreeRemoveAttempted: true,
    });
    context.onPreviewDeleteMutationIntent = ({ attempt }) => {
      if (attempt !== recovery.cleanup_preview_delete_intents + 1) {
        fail("DELTA20_INTERRUPTED_EXECUTION_PREVIEW_INTENT_SEQUENCE");
      }
      recovery = persistDelta20RuntimeExecutionRecovery(retained.root, {
        ...recovery,
        budget_snapshot: delta20ProjectedBudgetSnapshot(budgets, {
          vercelControlInvocations: 1,
          vercelDirectDeleteAttempts: 1,
        }),
        cleanup_preview_delete_intents: attempt,
      }).value;
    };
    verifyVercelProject(budgets);
    let previewResolved = false;
    try {
      const resolved = resolveExactHeaderQualifiedPreview(
        context,
        retained.state,
        "runtimeIdentity",
      );
      context.deploymentHostname = resolved.hostname;
      context.deploymentRecord = resolved.record;
      validatePersistedDeploymentState(context);
      previewResolved = true;
    } catch {
      await verifyPreviewAbsent(context);
      context.previewRemoved = true;
    }
    verifyDelta15TemporaryBranchAbsentTwice(
      context,
      "DELTA20_INTERRUPTED_EXECUTION_BRANCH_ABSENCE",
    );
    adminPasswordBytes = readProtectedDelta13AdminPassword(
      repositoryRoot,
      budgets,
    );
    const cleanupEnvironment = readProtectedDelta15QualificationEnvironment(
      repositoryRoot,
      budgets,
      adminPasswordBytes,
    );
    const priorBudgets = new Delta17APriorReconciliationBudgets();
    const direct = await createCountedSupabase(
      cleanupEnvironment.environment,
      cleanupEnvironment.confirmedOrigin,
      priorBudgets,
    );
    const prior = await reconcileDelta17APriorResidue({
      budgets: priorBudgets,
      classifiers: buildDelta20InterruptedRuntimeClassifiers(recovery),
      direct,
    });
    if (
      prior.evidence.zero_residue !== true ||
      prior.evidence.ownership_ambiguity !== 0
    ) {
      fail("DELTA20_INTERRUPTED_EXECUTION_DATA_RESIDUE");
    }
    context.dataCleaned = true;
    if (previewResolved) await deleteAndVerifyPreview(context);
    const finalEnvironment = captureDelta13EnvironmentSnapshot(
      budgets,
      "DELTA20_INTERRUPTED_EXECUTION_ENVIRONMENT_ABSENCE",
    );
    assertDelta13EnvironmentRestored(
      retained.state.environment_before,
      finalEnvironment,
      "DELTA20_INTERRUPTED_EXECUTION_ENVIRONMENT_ABSENCE",
    );
    if (!context.previewRemoved || !context.dataCleaned) {
      fail("DELTA20_INTERRUPTED_EXECUTION_EXTERNAL_RESIDUE");
    }
    const cleanupProofSha256 = sha256(canonicalJson({
      application_requests_replayed: 0,
      branch_remaining: 0,
      preview_remaining: 0,
      prior_reconciliation_evidence_sha256: prior.evidence_sha256,
      runtime_sessions_recreated: 0,
      zero_residue: true,
    }));
    recovery = persistDelta20RuntimeExecutionRecovery(retained.root, {
      ...recovery,
      budget_snapshot: delta13BudgetSnapshot(budgets),
      cleanup_proof_sha256: cleanupProofSha256,
      prior_reconciliation_evidence_sha256: prior.evidence_sha256,
      state: "ABORTED_CLEANUP_COMPLETE",
    }).value;
    finishDelta20InterruptedExecutionLocalArtifacts(retained, plan);
    releaseDelta20ExecutionLock(executionLock);
    executionLockReleased = true;
    failureEvidence = {
      cleanup_complete: "true",
      data_requests: direct.counts().directTotal,
      data_writes: "0",
      external_mutations: "occurred_and_cleaned",
      runtime_requests: 0,
    };
    process.stdout.write(
      `PASS_ADMIN_V1_DELTA20_INTERRUPTED_RUNTIME_CLEANUP last_attempted_ordinal=${recovery.last_attempted_ordinal} last_completed_ordinal=${recovery.last_completed_ordinal} application_requests=0 runtime_sessions=0 request_replays=0 attempt_spent=true cleanup_complete=true failures=0 internal_failures=0\n`,
    );
  } finally {
    if (adminPasswordBytes) adminPasswordBytes.fill(0);
    if (!executionLockReleased) {
      try {
        releaseDelta20ExecutionLock(executionLock);
      } catch {
        failureEvidence.cleanup_complete = "false";
      }
    }
  }
}

